# -*- coding: utf-8 -*-
"""Erzeugt die SQL-INSERTs für den EUDR-Strang (Stand 13.11.2026). Alle Datensätze: review_status entwurf, ausspielen false."""
import json

RS = "2026-11-13"
FLAG_NEU = "(neu 11/2026) EUDR-Strang, Erstfassung 13.11.2026. "

def q(s):
    return "'" + s.replace("'", "''") + "'"

def arr(xs, typ="text"):
    if not xs:
        return f"array[]::{typ}[]"
    if typ == "int":
        return "array[" + ",".join(str(x) for x in xs) + "]::int[]"
    return "array[" + ",".join(q(x) for x in xs) + "]::text[]"

