# ---------------------------------------------------------------- Glossar L68–L79
GLO = [
    (68, "L68", "EUDR (Entwaldungsverordnung)", "begriff", "Verordnung (EU) 2023/1115 über entwaldungsfreie Lieferketten. Verbietet ab dem 30.12.2026, bestimmte Rohstoffe und daraus hergestellte Erzeugnisse (u. a. Holz, Papier, Pappe, Naturkautschuk) in Verkehr zu bringen, wenn sie nicht entwaldungsfrei und legal erzeugt sind und keine Sorgfaltserklärung vorliegt. Geändert durch VO (EU) 2024/3234, VO (EU) 2025/2650 und Del. VO (EU) 2026/2102.", "Anhang I nach HS-Codes; Rollen Marktteilnehmer, nachgelagerter Marktteilnehmer, Händler; Informationssystem; Länder-Benchmarking."),
    (69, "L69", "Relevantes Erzeugnis (EUDR)", "begriff", "Erzeugnis, das in Anhang I der EUDR gelistet ist und relevante Rohstoffe enthält, mit ihnen gefüttert wurde oder unter ihrer Verwendung hergestellt wurde (Art. 2 Nr. 2). Für Verpackung: Holzverpackungen und Paletten (ex 4415), Halbstoffe (ex 47), Papier und Pappe einschließlich Waren daraus (ex 48). Nicht erfasst: Verpackung, die ein anderes Erzeugnis stützt, schützt oder trägt und mit ihm angeboten wird; gebrauchte Erzeugnisse; Rezyklat.", "Listung nach HS-Code; Ausnahmen im Anhang I i. d. F. Del. VO (EU) 2026/2102."),
    (70, "L70", "Entwaldungsfrei", "begriff", "Erzeugnisse, deren relevante Rohstoffe auf Flächen erzeugt wurden, die nach dem 31.12.2020 nicht entwaldet wurden, und – bei Holz – das ohne Waldschädigung nach diesem Stichtag geschlagen wurde (Art. 2 Nr. 13). Der Nachweis erfolgt über die Geolokalisierung der Grundstücke und die Sorgfaltserklärung des Marktteilnehmers.", "Stichtag 31.12.2020; Bezug auf Grundstücke."),
    (71, "L71", "Marktteilnehmer (EUDR)", "begriff", "Wer im Rahmen einer gewerblichen Tätigkeit ein relevantes Erzeugnis erstmals auf dem Unionsmarkt bereitstellt oder ausführt (Art. 2 Nr. 15, 16). Trägt die Sorgfaltspflicht und gibt die Sorgfaltserklärung ab. Für Verpackung: Papier- und Pappefabriken, Palettenhersteller, Importeure aus Drittländern. Entspricht dem englischen „operator“; nicht zu verwechseln mit dem Erzeuger oder Hersteller der PPWR.", "Erstes Inverkehrbringen; Sorgfaltserklärung; Referenznummer."),
    (72, "L72", "Nachgelagerter Marktteilnehmer (EUDR)", "begriff", "Wer relevante Erzeugnisse in Verkehr bringt, die unter Verwendung relevanter Erzeugnisse mit Sorgfaltserklärung hergestellt wurden (Art. 2 Nr. 15b, eingeführt durch VO (EU) 2025/2650). Kennzeichen: Verarbeitung mit Wechsel des HS-Codes. Pflichten nach Art. 5 (Informationen sammeln, Nicht-KMU: Registrierung), keine eigene Sorgfaltserklärung. Regelfall für Kartonagen- und Wellpappenhersteller mit EU-Papier.", "„downstream operator“; Art. 5 statt Art. 4."),
    (73, "L73", "Händler (EUDR)", "begriff", "Wer in der Lieferkette relevante Erzeugnisse auf dem Markt bereitstellt, ohne Marktteilnehmer oder nachgelagerter Marktteilnehmer zu sein (Art. 2 Nr. 17) – also unverändert weiterverkauft. Pflichten nach Art. 5 wie der nachgelagerte Marktteilnehmer. Nicht identisch mit dem Vertreiber der PPWR.", "„trader“; unveränderter Weiterverkauf."),
    (74, "L74", "Sorgfaltserklärung (DDS)", "objekt", "Erklärung des Marktteilnehmers über das EU-Informationssystem, dass die Sorgfaltspflicht erfüllt wurde und kein oder nur ein vernachlässigbares Risiko besteht (Art. 4 Abs. 2, Anhang II). Das System vergibt eine Referenznummer, die an nachgelagerte Marktteilnehmer und Händler weitergegeben wird (Art. 4 Abs. 7) und in die Zollanmeldung gehört (Art. 26). Nur Marktteilnehmer geben sie ab.", "„due diligence statement“; Referenznummer; fünf Jahre Aufbewahrung."),
    (75, "L75", "Referenznummer (EUDR)", "objekt", "Vom Informationssystem vergebene Nummer einer Sorgfaltserklärung (bzw. Identifikationsnummer einer vereinfachten Erklärung). Nachgelagerte Marktteilnehmer und Händler halten die Nummern ihrer Lieferanten fest, sofern diese Marktteilnehmer sind (Art. 5 Abs. 3 lit. a); eine Prüfung der Nummern ist nicht verlangt (FAQ v5, 3.4, unverbindlich).", "Weitergabepflicht beim Marktteilnehmer (Art. 4 Abs. 7)."),
    (76, "L76", "Informationssystem (EUDR)", "objekt", "Von der Kommission betriebenes elektronisches System nach Art. 33 (TRACES-Modul), über das Sorgfaltserklärungen und vereinfachte Erklärungen übermittelt werden und in dem sich Nicht-KMU-nachgelagerte Marktteilnehmer und Nicht-KMU-Händler registrieren müssen (Art. 5 Abs. 2). (!) Stand der Wiederinbetriebnahme mit neuen Funktionen (laut Kommission ab Juni 2026) prüfen.", "Registrierung; Übermittlung; Referenznummern."),
    (77, "L77", "Länder-Benchmarking (EUDR)", "begriff", "Einstufung der Erzeugerländer durch die Kommission in geringes, normales und hohes Risiko (Art. 29). Bei Rohstoffen aus Ländern mit geringem Risiko gilt die vereinfachte Sorgfaltspflicht (Art. 13): Informationssammlung ohne Risikobewertung und -minderung. (!) Durchführungsverordnung mit Länderliste vor Freigabe pinnen.", "Dreistufige Einstufung; vereinfachte Sorgfaltspflicht."),
    (78, "L78", "Wiedergewinnungsprodukt (EUDR)", "material", "Abfälle und Ausschuss sowie daraus gewonnene Erzeugnisse, die Anhang I vom Anwendungsbereich ausnimmt (Einträge ex 47 und ex 48 i. d. F. Del. VO (EU) 2026/2102). Nach der Kommissions-FAQ (2.8, unverbindlich) nur bei vollständig rezyklierten Erzeugnissen; jeder Frischfaseranteil ist erfasst. (!) Reichweite offen.", "Rezyklat; Altpapier; Frischfaseranteil."),
    (79, "L79", "Kleinst- oder Kleinprimärerzeuger (EUDR)", "begriff", "Kleinst- oder kleine Unternehmen, die relevante Rohstoffe in einem Land mit geringem Risiko selbst anbauen, ernten oder gewinnen (Art. 2 Nr. 15a). Für sie gilt die vereinfachte Regelung des Art. 4a (einmalige vereinfachte Erklärung statt Sorgfaltserklärung). Betrifft Forst- und Landwirtschaftsbetriebe, nicht Verpackungsunternehmen.", "Art. 4a; einmalige vereinfachte Erklärung; Identifikationsnummer."),
]

# ---------------------------------------------------------------- SQL
out = []
# Rollen-Definitionen
rows = []
for r in ROLLEN:
    rows.append(f"({q(r['rolle_id'])}, 'eudr', {q(r['begriff_de'])}, {q(r['begriff_en'])}, {q(r['fundstelle'])}, {q(r['definition'])}, {q(r['abgrenzung'])}, {q(r['verwechslung'])}, {q(r['flag'])}, true, 'entwurf', '{RS}')")
out.append("insert into rollen_definitionen (rolle_id, typ, begriff_de, begriff_en, fundstelle_ppwr, definition_kurz, abgrenzung, verwechslungsfaelle, flag, aktiv, review_status, rechtsstand) values\n" + ",\n".join(rows) + ";")

# Anforderungen
rows = []
for a in ANF:
    rows.append("(" + ", ".join([
        str(a['nr']), q(a['titel']), q(a['kategorie']), q(a['gilt_status']), q(a['gilt_ab']), q(a['rechtsquelle']),
        arr(a['betrifft']), q(a['kurz']), q(a['fachlich']), q(a['rechtstext']), q(json.dumps({"text": a['tatbestand']}, ensure_ascii=False)) + "::jsonb",
        q(json.dumps(a['folgen'], ensure_ascii=False)) + "::jsonb", q(a['handlung']), q(a['risiko']), q(a['ausnahmen']), q(a['uebergang']), q(a['layer']),
        "'entwurf'", f"'{RS}'", "false", "1"]) + ")")
out.append("insert into anforderungen (nr, titel, kategorie, gilt_status, gilt_ab, rechtsquelle, betrifft_rollen, kurzerklaerung, erklaerung_fachlich, erklaerung_rechtstext, tatbestand, rechtsfolgen_je_rolle, handlungsanweisung, risiko_bei_verstoss, ausnahmen, uebergangsregeln, verpackdg_layer, review_status, rechtsstand, ausspielen, version) values\n" + ",\n".join(rows) + ";")

# Praxisfragen
rows = []
for p in PF:
    rows.append("(" + ", ".join([str(p['nr']), q(p['code']), q(p['kurztitel']), q(p['frage']), q(p['antwort']), "'eudr'", arr(p['quellen']), q(p['verbindlichkeit']), q(p['flag']), arr(p['bezug_nr'], 'int'), "'entwurf'", f"'{RS}'", "false"]) + ")")
out.append("insert into auslegungen (nr, code, kurztitel, frage, antwort, kategorie, quellen, verbindlichkeit, flag, bezug_nr, review_status, rechtsstand, ausspielen) values\n" + ",\n".join(rows) + ";")

# Regeln
rows = []
for r in REG:
    rows.append("(" + ", ".join([q(r['id']), "'eudr'", str(r['prio']), q(r['wenn']), q(r['dann']), q(r['prim']), (q(r['sek']) if r['sek'] else 'null'), q(r['erl']), (q(FLAG_NEU + r['flag']) if r['flag'] else q(FLAG_NEU.strip())), "'verpackung'", "'entwurf'", f"'{RS}'"]) + ")")
out.append("insert into rollen_regeln (regel_id, block, prioritaet, wenn_bedingung, dann_rollen, fundstelle_primaer, fundstelle_sekundaer, erlaeuterung, flag, geltungsebene, review_status, rechtsstand) values\n" + ",\n".join(rows) + ";")

# Glossar
rows = []
for nr, code, lemma, typ, kurz, merk in GLO:
    rows.append("(" + ", ".join([str(nr), q(code), q(lemma), q(typ), q(kurz), q(merk), "array[41,42,43,44]::int[]", arr(['E01', 'E06']), q(FLAG_NEU.strip()), "'entwurf'", f"'{RS}'", "false"]) + ")")
out.append("insert into glossar_lemmata (nr, code, lemma, typ, kurzerklaerung, merkmale, verweis_anforderungen, verweis_auslegungen, flag, review_status, rechtsstand, ausspielen) values\n" + ",\n".join(rows) + ";")

